import { ATTACHMENT_EXTENSION_BY_MIME } from "./attachment.constants"

export function buildAttachmentObjectPath(input: {
  workspaceId: string
  taskId: string
  attachmentId: string
  mimeType: keyof typeof ATTACHMENT_EXTENSION_BY_MIME
}) {
  const ext = ATTACHMENT_EXTENSION_BY_MIME[input.mimeType]
  return `workspaces/${input.workspaceId}/tasks/${input.taskId}/${input.attachmentId}.${ext}`
}

